  5	public final class RabinKarp {
  6	
  7	    private static final int RADIX = 256;
  8	    private static final int MODULUS = 101;
  9	
 10	    private RabinKarp() {
 11	    }
 12	
 13	    public static List<Integer> search(CharSequence pattern, CharSequence text) {
 14	        return SearchInput.of(pattern, text).findMatches();
 15	    }
 16	
 17	    private static List<Integer> noMatches() {
 18	        return new ArrayList<>();
 19	    }
 20	
 21	    private static List<Integer> allStartIndexes(int textLength) {
 22	        List<Integer> matches = new ArrayList<>(textLength + 1);
 23	        for (int i = 0; i <= textLength; i++) {
 24	            matches.add(i);
 25	        }
 26	        return matches;
 27	    }
