 29	    private static final class SearchInput {
 30	        private final String text;
 31	        private final SearchPattern pattern;
 32	
 33	        private SearchInput(String text, SearchPattern pattern) {
 34	            this.text = text;
 35	            this.pattern = pattern;
 36	        }
 37	
 38	        private static SearchInput of(CharSequence pattern, CharSequence text) {
 39	            String normalizedPattern = Objects.requireNonNull(
 40	                pattern,
 41	                "Pattern must be non-null."
 42	            ).toString();
 43	            String normalizedText = Objects.requireNonNull(
 44	                text,
 45	                "Text must be non-null."
 46	            ).toString();
 47	
 48	            return new SearchInput(normalizedText, new SearchPattern(normalizedPattern));
 49	        }
 50	
 51	        private boolean hasEmptyPattern() {
 52	            return pattern.isEmpty();
 53	        }
 54	
 55	        private boolean hasMatchableWindow() {
 56	            return pattern.length() <= text.length();
 57	        }
 58	
 59	        private int textLength() {
 60	            return text.length();
 61	        }
 62	
 63	        private List<Integer> findMatches() {
 64	            if (hasEmptyPattern()) {
 65	                return allStartIndexes(textLength());
 66	            }
 67	
 68	            if (!hasMatchableWindow()) {
 69	                return noMatches();
 70	            }
 71	
 72	            return new SearchSession(text, pattern).findMatches();
 73	        }
 74	    }
