 76	    private static final class SearchPattern {
 77	        private final String value;
 78	        private final int length;
 79	        private final int hash;
 80	        private final int highOrderMultiplier;
 81	
 82	        private SearchPattern(String value) {
 83	            this.value = value;
 84	            this.length = value.length();
 85	            this.hash = RollingHash.compute(value, length);
 86	            this.highOrderMultiplier = computeHighOrderMultiplier(length);
 87	        }
 88	
 89	        private boolean isEmpty() {
 90	            return length == 0;
 91	        }
 92	
 93	        private int length() {
 94	            return length;
 95	        }
 96	
 97	        private int hash() {
 98	            return hash;
 99	        }
100	
101	        private int highOrderMultiplier() {
102	            return highOrderMultiplier;
103	        }
104	
105	        private boolean matches(String text, int startIndex) {
106	            for (int i = 0; i < length; i++) {
107	                if (text.charAt(startIndex + i) != value.charAt(i)) {
108	                    return false;
109	                }
110	            }
111	            return true;
112	        }
113	    }
