115	    private static final class SearchSession {
116	        private final SearchPattern pattern;
117	        private final TextWindow window;
118	        private int startIndex;
119	
120	        private SearchSession(String text, SearchPattern pattern) {
121	            this.pattern = pattern;
122	            this.window = new TextWindow(text, pattern.length());
123	        }
124	
125	        private List<Integer> findMatches() {
126	            List<Integer> matches = new ArrayList<>(windowCount());
127	            while (hasCurrentWindow()) {
128	                if (isMatch()) {
129	                    matches.add(startIndex);
130	                }
131	                advance();
132	            }
133	            return matches;
134	        }
135	
136	        private boolean hasCurrentWindow() {
137	            return startIndex <= window.lastStartIndex();
138	        }
139	
140	        private int windowCount() {
141	            return window.lastStartIndex() + 1;
142	        }
143	
144	        private boolean isMatch() {
145	            return pattern.hash() == window.hash()
146	                && pattern.matches(window.text(), startIndex);
147	        }
148	
149	        private void advance() {
150	            if (startIndex < window.lastStartIndex()) {
151	                window.slide(pattern.highOrderMultiplier(), startIndex);
152	            }
153	            startIndex++;
154	        }
155	    }
