157	    private static final class TextWindow {
158	        private final String text;
159	        private final int windowLength;
160	        private int hash;
161	
162	        private TextWindow(String text, int windowLength) {
163	            this.text = text;
164	            this.windowLength = windowLength;
165	            this.hash = RollingHash.compute(text, windowLength);
166	        }
167	
168	        private int lastStartIndex() {
169	            return text.length() - windowLength;
170	        }
171	
172	        private int hash() {
173	            return hash;
174	        }
175	
176	        private String text() {
177	            return text;
178	        }
179	
180	        private void slide(int highOrderMultiplier, int startIndex) {
181	            hash = RollingHash.roll(
182	                hash,
183	                text.charAt(startIndex),
184	                text.charAt(startIndex + windowLength),
185	                highOrderMultiplier
186	            );
187	        }
188	    }
