190	    private static final class RollingHash {
191	        private RollingHash() {
192	        }
193	
194	        private static int compute(String value, int length) {
195	            int hash = 0;
196	            for (int i = 0; i < length; i++) {
197	                hash = (RADIX * hash + value.charAt(i)) % MODULUS;
198	            }
199	            return hash;
200	        }
201	
202	        private static int roll(
203	            int currentHash,
204	            char outgoingChar,
205	            char incomingChar,
206	            int highOrderMultiplier
207	        ) {
208	            int nextHash = (
209	                RADIX * (currentHash - outgoingChar * highOrderMultiplier) + incomingChar
210	            ) % MODULUS;
211	
212	            if (nextHash < 0) {
213	                nextHash += MODULUS;
214	            }
215	
216	            return nextHash;
217	        }
218	    }
219	
220	    private static int computeHighOrderMultiplier(int patternLength) {
221	        int highOrderMultiplier = 1;
222	        for (int i = 0; i < patternLength - 1; i++) {
223	            highOrderMultiplier = (highOrderMultiplier * RADIX) % MODULUS;
224	        }
225	        return highOrderMultiplier;
226	    }
