229	        String txt = "geeksforgeeks";
230	        String pat = "geeks";
231	        List<Integer> res = search(pat, txt);
232	        for (int idx : res) {
233	            System.out.print(idx + " ");
234	        }
235	        System.out.println();
236	    }
