 4	public final class RabinKarpTest {
 5	
 6	    private RabinKarpTest() {
 7	    }
 8	
 9	    public static void main(String[] args) {
10	        assertMatches("finds repeated matches", "geeks", "geeksforgeeks", 0, 8);
11	        assertMatches("finds overlapping matches", "aa", "aaaa", 0, 1, 2);
12	        assertMatches("supports empty patterns", "", "abc", 0, 1, 2, 3);
13	        assertMatches("returns no matches when pattern is longer", "abcd", "abc");
14	        assertMatches(
15	            "accepts non-string CharSequence inputs",
16	            new StringBuilder("aba"),
17	            new StringBuffer("ababa"),
18	            0,
19	            2
20	        );
21	        assertMatches("supports empty text", "a", "");
22	        assertThrowsNullPointer(
23	            "rejects null pattern",
24	            "Pattern must be non-null.",
25	            () -> RabinKarp.search(null, "abc")
26	        );
27	        assertThrowsNullPointer(
28	            "rejects null text",
29	            "Text must be non-null.",
30	            () -> RabinKarp.search("abc", null)
31	        );
32	    }
33	
34	    private static void assertMatches(
35	        String scenario,
36	        CharSequence pattern,
37	        CharSequence text,
38	        Integer... expected
39	    ) {
40	        List<Integer> actual = RabinKarp.search(pattern, text);
41	        List<Integer> expectedMatches = Arrays.asList(expected);
42	        if (!actual.equals(expectedMatches)) {
43	            throw new AssertionError(
44	                scenario + ": expected " + expectedMatches + " but got " + actual
45	            );
46	        }
47	    }
48	
49	    private static void assertThrowsNullPointer(
50	        String scenario,
51	        String expectedMessage,
52	        Runnable action
53	    ) {
54	        try {
55	            action.run();
56	            throw new AssertionError(scenario + ": expected NullPointerException");
57	        } catch (NullPointerException expected) {
58	            if (!expectedMessage.equals(expected.getMessage())) {
59	                throw new AssertionError(
60	                    scenario + ": expected message '" + expectedMessage
61	                        + "' but got '" + expected.getMessage() + "'"
62	                );
63	            }
64	        }
65	    }
66	}

